{
  "decision-month-end-earned-premium-rollforward": "WITH tranches AS (SELECT pool_code, signed_cents, book_day, julianday(first_day) AS start_jd, CAST(julianday(stop_day) - julianday(first_day) AS INTEGER) AS duration FROM premium_tranche WHERE book_day <= '2025-11-30'), covered AS (SELECT *, CASE WHEN book_day <= '2025-10-31' THEN max(0, min(duration, CAST(julianday('2025-11-01') - start_jd AS INTEGER))) ELSE 0 END AS oct_days, max(0, min(duration, CAST(julianday('2025-12-01') - start_jd AS INTEGER))) AS nov_days FROM tranches), earned AS (SELECT pool_code, signed_cents, (signed_cents / duration) * oct_days + (signed_cents % duration) * oct_days / duration AS oct_earned, (signed_cents / duration) * nov_days + (signed_cents % duration) * nov_days / duration AS nov_earned FROM covered) SELECT pool_code, sum(nov_earned - oct_earned) AS november_earned_cents, sum(signed_cents - nov_earned) AS closing_unearned_cents FROM earned GROUP BY pool_code ORDER BY pool_code COLLATE BINARY",
  "decision-mural-progress-payment": "WITH latest AS (SELECT r.*, earned_cents / 10 - (earned_cents % 10 < 0) AS held_cents FROM mural_review AS r WHERE review_no = (SELECT max(s.review_no) FROM mural_review AS s WHERE s.mural_code = r.mural_code)) SELECT r.mural_code, r.source_id AS review_source, r.held_cents, max(0, r.earned_cents - r.held_cents - coalesce((SELECT sum(p.cash_cents) FROM cash_posting AS p WHERE p.mural_code = r.mural_code AND p.posted_review <= r.review_no), 0)) AS installment_cents FROM latest AS r ORDER BY r.mural_code COLLATE BINARY",
  "decision-net-currency-pocket-conversion": "WITH nets AS (SELECT run_code, pocket_code, sum(source_units) AS units FROM pocket_entries GROUP BY run_code, pocket_code), amounts AS (SELECT run_code, units * cent_num AS numerator, unit_den AS denominator FROM nets JOIN pocket_quotes USING (run_code, pocket_code)) SELECT run_code, sum(numerator / denominator + CASE WHEN abs(numerator % denominator) >= denominator / 2 + denominator % 2 THEN CASE WHEN numerator < 0 THEN -1 ELSE 1 END ELSE 0 END) AS payout_cents FROM amounts GROUP BY run_code ORDER BY run_code",
  "decision-net-interbranch-premium-settlement-csv": "WITH pairs AS (SELECT min(beneficiary, funding_branch) AS lo, max(beneficiary, funding_branch) AS hi, ccy, CASE WHEN beneficiary < funding_branch THEN allocation_cents ELSE -allocation_cents END AS signed_amount FROM funding_entry WHERE beneficiary <> funding_branch), balances AS (SELECT lo, hi, ccy, sum(signed_amount) AS net FROM pairs GROUP BY lo, hi, ccy HAVING sum(signed_amount) <> 0), payables AS (SELECT CASE WHEN net > 0 THEN lo ELSE hi END AS debtor, CASE WHEN net > 0 THEN hi ELSE lo END AS creditor, ccy, abs(net) AS cents FROM balances) SELECT 'debtor,creditor,currency,cents' || char(10) || coalesce(group_concat(line, ''), '') AS csv_contents FROM (SELECT debtor || ',' || creditor || ',' || ccy || ',' || cents || char(10) AS line FROM payables ORDER BY debtor COLLATE BINARY, creditor COLLATE BINARY, ccy COLLATE BINARY)"
}
